from wsgiref.util import setup_testing_defaults

def app(environ, start_response):
    start_response('200 OK', [('Content-Type', 'text/plain')])
    return [b'ok']

def with_demo_header(inner_app):
    def wrapped(environ, start_response):
        def add_header(status, headers, exc_info=None):
            return start_response(status, [*headers, ('X-Demo', 'yes')], exc_info)
        return inner_app(environ, add_header)
    return wrapped

environ = {}
setup_testing_defaults(environ)
seen = []
def capture(status, headers, exc_info=None):
    seen.append((status, dict(headers)))
    return lambda chunk: None
body = b''.join(with_demo_header(app)(environ, capture))
assert body == b'ok' and seen[0][0] == '200 OK'
assert seen[0][1]['Content-Type'] == 'text/plain'
assert seen[0][1]['X-Demo'] == 'yes'
print(body.decode())
